"""Frozen Wave3 DDL; independent of future ORM edits."""
# ruff: noqa: E501

TABLES = ('bom_revisions', 'parts', 'bom_lines', 'engineering_configurations', 'process_revisions', 'builds', 'build_readiness')

SCHEMA_SQL = (
    "\nCREATE TABLE bom_revisions (\n\tseries_id UUID NOT NULL, \n\tprevious_id UUID, \n\texpected_previous_revision INTEGER, \n\treason TEXT NOT NULL, \n\tproduct_id UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\tname VARCHAR(200) NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\trevision INTEGER NOT NULL, \n\tsources JSONB NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, id, revision), \n\tFOREIGN KEY(tenant_id, product_id) REFERENCES products (tenant_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (visibility IN ('private','product') AND status = 'draft'), \n\tUNIQUE (tenant_id, product_id, series_id, revision), \n\tFOREIGN KEY(tenant_id, product_id, series_id) REFERENCES bom_revisions (tenant_id, product_id, id), \n\tFOREIGN KEY(tenant_id, product_id, previous_id, expected_previous_revision) REFERENCES bom_revisions (tenant_id, product_id, id, revision), \n\tCHECK ((previous_id IS NULL AND expected_previous_revision IS NULL AND revision = 1 AND series_id = id) OR (previous_id IS NOT NULL AND previous_id <> id AND expected_previous_revision > 0 AND revision = expected_previous_revision + 1))\n)\n\n",
    'CREATE INDEX ix_bom_revisions_tenant_id ON bom_revisions (tenant_id)',
    "\nCREATE TABLE parts (\n\tinternal_number VARCHAR(100), \n\terp_number VARCHAR(100), \n\tcustomer_number VARCHAR(100), \n\tmapping_version VARCHAR(100), \n\texternal_design_refs JSONB NOT NULL, \n\tproduct_id UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\tname VARCHAR(200) NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\trevision INTEGER NOT NULL, \n\tsources JSONB NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, id, revision), \n\tFOREIGN KEY(tenant_id, product_id) REFERENCES products (tenant_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (visibility IN ('private','product') AND status = 'draft'), \n\tCHECK (revision = 1)\n)\n\n",
    'CREATE INDEX ix_parts_tenant_id ON parts (tenant_id)',
    '\nCREATE TABLE bom_lines (\n\tproduct_id UUID NOT NULL, \n\tbom_id UUID NOT NULL, \n\tkey VARCHAR(80) NOT NULL, \n\tpart_id UUID NOT NULL, \n\tpart_revision INTEGER NOT NULL, \n\tquantity NUMERIC(38, 12), \n\tunit VARCHAR(80), \n\tloss_rate NUMERIC(38, 12), \n\tcritical BOOLEAN NOT NULL, \n\tnotes TEXT, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, bom_id, key), \n\tFOREIGN KEY(tenant_id, product_id, bom_id) REFERENCES bom_revisions (tenant_id, product_id, id), \n\tFOREIGN KEY(tenant_id, product_id, part_id, part_revision) REFERENCES parts (tenant_id, product_id, id, revision), \n\tCHECK (quantity IS NULL OR (quantity > 0 AND unit IS NOT NULL)), \n\tCHECK (loss_rate IS NULL OR loss_rate >= 0)\n)\n\n',
    'CREATE INDEX ix_bom_lines_tenant_id ON bom_lines (tenant_id)',
    "\nCREATE TABLE engineering_configurations (\n\tdefinition_id UUID NOT NULL, \n\tdefinition_revision INTEGER NOT NULL, \n\tbom_id UUID NOT NULL, \n\tbom_revision INTEGER NOT NULL, \n\tdesign_versions JSONB NOT NULL, \n\tseries_id UUID NOT NULL, \n\tprevious_id UUID, \n\texpected_previous_revision INTEGER, \n\treason TEXT NOT NULL, \n\tproduct_id UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\tname VARCHAR(200) NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\trevision INTEGER NOT NULL, \n\tsources JSONB NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, id, revision), \n\tFOREIGN KEY(tenant_id, product_id) REFERENCES products (tenant_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (visibility IN ('private','product') AND status = 'draft'), \n\tUNIQUE (tenant_id, product_id, series_id, revision), \n\tFOREIGN KEY(tenant_id, product_id, series_id) REFERENCES engineering_configurations (tenant_id, product_id, id), \n\tFOREIGN KEY(tenant_id, product_id, previous_id, expected_previous_revision) REFERENCES engineering_configurations (tenant_id, product_id, id, revision), \n\tCHECK ((previous_id IS NULL AND expected_previous_revision IS NULL AND revision = 1 AND series_id = id) OR (previous_id IS NOT NULL AND previous_id <> id AND expected_previous_revision > 0 AND revision = expected_previous_revision + 1)), \n\tFOREIGN KEY(tenant_id, product_id, definition_id) REFERENCES definition_revisions (tenant_id, product_id, id), \n\tFOREIGN KEY(tenant_id, product_id, bom_id, bom_revision) REFERENCES bom_revisions (tenant_id, product_id, id, revision), \n\tCHECK (definition_revision > 0 AND bom_revision > 0)\n)\n\n",
    'CREATE INDEX ix_engineering_configurations_tenant_id ON engineering_configurations (tenant_id)',
    "\nCREATE TABLE process_revisions (\n\tengineering_configuration_id UUID NOT NULL, \n\tengineering_revision INTEGER NOT NULL, \n\toperations JSONB NOT NULL, \n\tsite VARCHAR(200), \n\tline VARCHAR(200), \n\tseries_id UUID NOT NULL, \n\tprevious_id UUID, \n\texpected_previous_revision INTEGER, \n\treason TEXT NOT NULL, \n\tproduct_id UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\tname VARCHAR(200) NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\trevision INTEGER NOT NULL, \n\tsources JSONB NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, id, revision), \n\tFOREIGN KEY(tenant_id, product_id) REFERENCES products (tenant_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (visibility IN ('private','product') AND status = 'draft'), \n\tUNIQUE (tenant_id, product_id, series_id, revision), \n\tFOREIGN KEY(tenant_id, product_id, series_id) REFERENCES process_revisions (tenant_id, product_id, id), \n\tFOREIGN KEY(tenant_id, product_id, previous_id, expected_previous_revision) REFERENCES process_revisions (tenant_id, product_id, id, revision), \n\tCHECK ((previous_id IS NULL AND expected_previous_revision IS NULL AND revision = 1 AND series_id = id) OR (previous_id IS NOT NULL AND previous_id <> id AND expected_previous_revision > 0 AND revision = expected_previous_revision + 1)), \n\tUNIQUE (tenant_id, product_id, engineering_configuration_id, id), \n\tFOREIGN KEY(tenant_id, product_id, engineering_configuration_id, engineering_revision) REFERENCES engineering_configurations (tenant_id, product_id, id, revision), \n\tCHECK (engineering_revision > 0)\n)\n\n",
    'CREATE INDEX ix_process_revisions_tenant_id ON process_revisions (tenant_id)',
    "\nCREATE TABLE builds (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tproject_revision INTEGER NOT NULL, \n\tengineering_configuration_id UUID NOT NULL, \n\tmanufacturing_configuration_id UUID NOT NULL, \n\tprevious_build_id UUID, \n\towner_id UUID NOT NULL, \n\tname VARCHAR(160) NOT NULL, \n\ttype VARCHAR(24) NOT NULL, \n\tpurpose TEXT NOT NULL, \n\tplanned_quantity NUMERIC(24, 8) NOT NULL, \n\tunit VARCHAR(80) NOT NULL, \n\tplanned_start TIMESTAMP WITH TIME ZONE, \n\tplanned_end TIMESTAMP WITH TIME ZONE, \n\tverification_objectives TEXT NOT NULL, \n\tdisposition_plan TEXT NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\trevision INTEGER NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id) REFERENCES projects (tenant_id, product_id, id), \n\tFOREIGN KEY(tenant_id, product_id, engineering_configuration_id) REFERENCES engineering_configurations (tenant_id, product_id, id), \n\tFOREIGN KEY(tenant_id, product_id, engineering_configuration_id, manufacturing_configuration_id) REFERENCES process_revisions (tenant_id, product_id, engineering_configuration_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, previous_build_id) REFERENCES builds (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (revision > 0 AND project_revision > 0 AND planned_quantity > 0), \n\tCHECK (visibility IN ('private','product') AND status = 'planned'), \n\tCHECK (type IN ('prototype','tool_trial','pilot')), \n\tCHECK (planned_end IS NULL OR planned_start IS NULL OR planned_end >= planned_start), \n\tCHECK (previous_build_id IS DISTINCT FROM id)\n)\n\n",
    'CREATE INDEX ix_builds_tenant_id ON builds (tenant_id)',
    "\nCREATE TABLE build_readiness (\n\tproduct_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tbuild_revision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\trevision INTEGER NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tresult JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, build_id, build_revision), \n\tFOREIGN KEY(tenant_id, product_id, build_id) REFERENCES builds (tenant_id, product_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (revision > 0 AND build_revision > 0 AND status = 'blocked'), \n\tCHECK (visibility IN ('private','product')), \n\tCHECK (jsonb_typeof(result) = 'object')\n)\n\n",
    'CREATE INDEX ix_build_readiness_tenant_id ON build_readiness (tenant_id)',
)
